import AppKit
import SwiftUI

/// A drag from the workroom tab bar into the split content (content-local point + the dragged tab's id).
struct WorkroomPaneDrag: Equatable {
  let sid: SidebarID
  var location: CGPoint
}

/// Workroom-into-workroom split renderer (issue #23 follow-up): renders `PaneLayout<SidebarID>` as
/// nested, resizable panes — each a full `TargetTerminalDetail`. Deliberately SEPARATE from the
/// terminal renderer `PaneTreeView` (whose re-parenting/blank-pane history makes surgery risky); it
/// reuses only the pure `PaneTreeLayout` geometry + the generic `PaneLayout` model and duplicates a
/// little view chrome (divider, focus border, drop band).
///
/// Like `PaneTreeView`, panes are laid out in ONE flat `ZStack`, positioned by absolute frames and
/// keyed by `SidebarID`, so a surviving pane keeps the exact same host across a layout change (only its
/// frame moves) — its terminal is never re-parented. `RootView` ALWAYS renders through this view when
/// the tab bar is on (a no-split case is just `.leaf(selected)`), so single↔split is a leaf-set change,
/// not a structural swap — the same lesson that made `WorkroomTerminalsView` always render through
/// `PaneTreeView`.
struct WorkroomSplitView: View {
  /// The app store, threaded to each leaf as a plain (non-observed) reference so the workroom
  /// context menu (issue #112) can read/mutate it WITHOUT subscribing this terminal-hosting view
  /// tree to the whole churny store. NOT `@EnvironmentObject`/`@ObservedObject` on purpose.
  let store: AppStore
  let layout: PaneLayout<SidebarID>
  /// Resolve a leaf to its live target (drops a since-deleted workroom). Owned by the store.
  let resolve: (SidebarID) -> TerminalTarget?
  let focusedID: SidebarID?
  /// The live drag of a workroom into the content — from the tab bar OR a split member's group title
  /// bar (issue #110). Drives the drop-edge highlight; a member's title bar writes it while dragging.
  @Binding var externalDrag: WorkroomPaneDrag?
  /// Content-local point for a global drag location (nil when over the title-bar strip). Owned by
  /// `RootView`; shared with the tab bar so a title-bar drag drops onto the same panes a chip would.
  let localize: (CGPoint) -> CGPoint?
  /// Where a drag at a global location lands (member pane + edge), or nil if not over a pane.
  let dropTarget: (CGPoint) -> (sid: SidebarID, edge: PaneEdge)?
  let onFocus: (SidebarID) -> Void
  let onSetRatio: (CGFloat, UUID) -> Void
  let onClose: (SidebarID) -> Void
  /// Move a member to land beside another at an edge (drag a group by its title bar). Wired to
  /// `store.insertWorkroomSplit`, the same transform the tab-bar chip drop uses.
  let onMove: (SidebarID, SidebarID, PaneEdge) -> Void

  private static let space = "workroomSplitContent"
  private let theme = ThemeService.shared

  var body: some View {
    let leaves = layout.tabIDs
    let multi = leaves.count >= 2
    GeometryReader { geo in
      let plan = PaneTreeLayout.plan(layout, in: CGRect(origin: .zero, size: geo.size))
      ZStack(alignment: .topLeading) {
        ForEach(leaves, id: \.self) { sid in
          if let target = resolve(sid), let rect = plan.panes[sid] {
            WorkroomPaneLeaf(
              store: store, sid: sid, target: target, focused: sid == focusedID, multi: multi,
              externalDrag: $externalDrag, localize: localize, dropTarget: dropTarget,
              onClose: { onClose(sid) }, onMove: onMove
            )
            .frame(width: rect.width, height: rect.height)
            .position(x: rect.midX, y: rect.midY)
            .id(sid)
            // A tap on the pane *chrome* focuses it. Clicking *into* the terminal is handled by the
            // first-responder → selection callback (the libghostty NSView eats SwiftUI taps).
            .onTapGesture { onFocus(sid) }
          }
        }
        ForEach(plan.dividers) { d in
          WorkroomSplitDivider(orientation: d.orientation, ratio: d.ratio, total: d.total) {
            onSetRatio($0, d.id)
          }
          .frame(width: d.hitRect.width, height: d.hitRect.height)
          .position(x: d.rect.midX, y: d.rect.midY)
        }
        dropHighlight(plan: plan)
      }
      .coordinateSpace(.named(Self.space))
    }
    // When split, hold the group cards off the left/right sidebars with an outer gutter (issue #110) —
    // applied outside the GeometryReader so the panes reflow within the inset. Solo is flush as before.
    .padding(.horizontal, multi ? 6 : 0)
  }

  /// The accent band previewing where a dragged workroom tab will land (mirrors `PaneTreeView`).
  @ViewBuilder
  private func dropHighlight(plan: PaneTreeLayout.Plan<SidebarID>) -> some View {
    if let drag = externalDrag,
      let hit = PaneTreeLayout.dropTarget(at: drag.location, panes: plan.panes),
      hit.tab != drag.sid, let rect = plan.panes[hit.tab]
    {
      let band = PaneTreeLayout.edgeBand(hit.edge, in: rect)
      RoundedRectangle(cornerRadius: 8)
        .fill(theme.tokens.accent.opacity(0.25))
        .overlay(RoundedRectangle(cornerRadius: 8).strokeBorder(theme.tokens.accent, lineWidth: 2))
        .frame(width: band.width, height: band.height)
        .position(x: band.midX, y: band.midY)
        .allowsHitTesting(false)
        .transition(.opacity)
    }
  }
}

/// Pure, testable mapping from a split member's `SidebarID` + its resolved `target` to the workroom
/// name shown in the group title bar. Extracted from `WorkroomPaneLeaf` so it is unit-testable without
/// instantiating the view (same rationale as `RootPresentation`).
///
/// INVARIANT: `target` MUST be the resolved target for `sid` (i.e. `AppStore.target(for: sid)`), so
/// `target.title` is *this* workroom's label-aware `displayName` (issue #41). A mismatched target would
/// display an unrelated title; the one caller satisfies this via `resolve(sid)`.
enum WorkroomSplitTitlePresentation {
  static func workroomName(sid: SidebarID, target: TerminalTarget) -> String? {
    // `target.title` is the label-aware `displayName`; NOT the raw `sid` name (issue #113).
    if case .workroom = sid { return target.title }
    return nil
  }
}

/// One workroom pane: the full terminal body + a focus border and a hover ✕ (remove from split). Solo
/// (`multi == false`) it's just the bare `TargetTerminalDetail`, so the single-workroom case renders
/// identically to the old `targetDetail` content.
private struct WorkroomPaneLeaf: View {
  /// Plain (non-observed) store reference for the group title bar's context menu (issue #112) —
  /// see `WorkroomSplitView.store`. NOT `@EnvironmentObject`: this view hosts a live terminal and
  /// must not re-evaluate on every unrelated store change.
  let store: AppStore
  let sid: SidebarID
  let target: TerminalTarget
  let focused: Bool
  let multi: Bool
  /// The shared workroom-drag state — the title bar writes it while dragging this group (issue #110).
  @Binding var externalDrag: WorkroomPaneDrag?
  let localize: (CGPoint) -> CGPoint?
  let dropTarget: (CGPoint) -> (sid: SidebarID, edge: PaneEdge)?
  let onClose: () -> Void
  let onMove: (SidebarID, SidebarID, PaneEdge) -> Void
  private let theme = ThemeService.shared

  var body: some View {
    // `content` MUST stay at ONE structural position across solo↔split (it's the second child of this
    // VStack in both cases) — the group title bar is a toggled *sibling* above it, never a wrapper
    // around it, and all card styling is applied as always-present modifiers whose *values* go neutral
    // when solo. A structural `if multi { VStack { titleBar; content } } else { content }` would swap
    // SwiftUI's `_ConditionalContent` branch when a 2-member split dissolves to solo (survivor flips
    // `multi: true→false`), tearing down + rebuilding `TargetTerminalDetail` and re-parenting the
    // libghostty surface — the blank/stranded-pane bug. This mirrors `PaneLeafView`, which keeps its
    // content in one slot and expresses the `multiPane` chrome as always-mounted overlays (issue #3).
    VStack(spacing: 0) {
      if multi {
        // A real split member: a group header (issue #110) tops the pane, identifying which workroom
        // this is, with the whole pane wrapped in a rounded card so members read as distinct units.
        WorkroomSplitGroupTitleBar(
          projectLabel: projectLabel, workroomName: workroomName, focused: focused,
          isMissing: target.isMissing, onClose: onClose
        )
        // Drag the group by its title bar to move the whole member within the split (issue #110) —
        // the SAME gesture/closures the tab-bar chip uses, so it drops onto the same panes and shows
        // the same drop-edge highlight. A plain click (no movement past `minimumDistance`) still
        // falls through to the leaf's focus tap.
        .gesture(
          DragGesture(minimumDistance: 6, coordinateSpace: .global)
            .onChanged { value in
              externalDrag = localize(value.location).map {
                WorkroomPaneDrag(sid: sid, location: $0)
              }
            }
            .onEnded { value in
              if let drop = dropTarget(value.location), drop.sid != sid {
                onMove(sid, drop.sid, drop.edge)
              }
              externalDrag = nil
            }
        )
        // The workroom's right-click menu (issue #112) — the SAME items as the tab chip (incl.
        // "Close"), PLUS a "Remove from Split" item (the menu equivalent of the title bar's ✕),
        // wired to the same `onClose` the ✕ uses. `closeName` matches the chip's `workroomName ??
        // primaryLabel`. Attached AFTER `.gesture` so both share the bar's `.contentShape`;
        // secondary-click (menu) and the primary-button drag coexist. The ✕ is its own hit target,
        // so a right-click directly on it won't raise this menu (expected — the menu covers the
        // rest of the bar).
        .contextMenu {
          workroomContextMenu(
            store: store, sid: sid, target: target, closeName: workroomName ?? projectLabel,
            onRemoveFromSplit: onClose)
        }
      }
      // Solo: `compact == false` → the bordered terminals inside do the framing and the card modifiers
      // below all go neutral, so the single-workroom case renders identically to before.
      content(compact: multi)
    }
    // No border in the split: the group reads as a unit by a subtle raised fill over the `panel` base
    // plus the shadow + rounded corners (issue #110). The focused member's fill is accent-tinted so
    // focus reads as a colour; the rest take a faint neutral lift — both dedicated theme tokens. Solo
    // takes `.clear`/no-shadow so these always-applied modifiers are visual no-ops (identity-stable).
    .background(
      multi
        ? (focused ? theme.tokens.splitGroupFocusedFill : theme.tokens.splitGroupFill) : Color.clear
    )
    .background(multi ? theme.tokens.panel : Color.clear)
    .clipShape(RoundedRectangle(cornerRadius: multi ? 8 : 0, style: .continuous))
    .shadow(
      color: .black.opacity(multi ? (focused ? 0.18 : 0.10) : 0),
      radius: multi ? (focused ? 6 : 3) : 0, y: multi ? 2 : 0
    )
    // Split: a clear inter-group gutter on every side (the title bar sits at the pane's top). Solo:
    // the 2pt gutter on sides + bottom but NOT the top, so the terminal tab strip aligns with the top
    // of the sidebar. Always-applied (value-only change) so it never flips a structural branch.
    .padding(
      multi
        ? EdgeInsets(top: 4, leading: 4, bottom: 4, trailing: 4)
        : EdgeInsets(top: 0, leading: 2, bottom: 2, trailing: 2)
    )
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier("workroom.pane")
    .accessibilityLabel(Text("Workroom \(target.title)"))
    .accessibilityAddTraits(focused && multi ? .isSelected : [])
  }

  /// The project name — the chip's primary label format (`AppStore.projectPath` last component),
  /// matching `WorkroomTabChip.primaryLabel`. Empty only if the sid resolves no project (never for a
  /// real split member).
  private var projectLabel: String {
    AppStore.projectPath(of: sid).map { ($0 as NSString).lastPathComponent } ?? ""
  }

  /// This member's own display name (nil for a project root) — the label-aware `target.title`,
  /// resolved through `WorkroomSplitTitlePresentation` so a relabel (issue #41) shows here
  /// immediately. Feeds both the title bar's visible text and its accessibility label (issue #113);
  /// NOT the raw `SidebarID` name, which never changes on relabel.
  private var workroomName: String? {
    WorkroomSplitTitlePresentation.workroomName(sid: sid, target: target)
  }

  @ViewBuilder
  private func content(compact: Bool) -> some View {
    if target.isMissing {
      // The workroom's directory has gone away (deleted on disk). Don't mount a terminal over a dead
      // path — show the same "Directory not found" state the solo detail uses. A co-displayed member
      // must be guarded here: `RootView`'s solo `isMissing` branch only covers the *selected* target,
      // so without this a non-focused member with a vanished path would render live terminal chrome
      // (issue #23 follow-up). The way out of the split is the title bar's ✕ (issue #110), which the
      // leaf draws above this content for every split member.
      ContentUnavailableView {
        Label("Directory not found", systemImage: "questionmark.folder")
      } description: {
        Text("\(target.title) points at a path that no longer exists.\n\(target.path)")
      }
      .frame(maxWidth: .infinity, maxHeight: .infinity)
    } else {
      // `surfaceActive: focused` so only the focused workroom pane's terminal grabs first responder —
      // a co-displayed non-focused pane must not steal focus (and retarget the selection) as it mounts.
      // The remove-from-split control now lives in the leaf's title bar (issue #110), not on the strip.
      TargetTerminalDetail(target: target, surfaceActive: focused, compact: compact)
    }
  }
}

/// The group header atop each workroom-split member (issue #110): a leading cube glyph, the
/// `project / workroom` label (matching the tab chip's format), and the relocated remove-from-split ✕.
/// Shown only for a real split member (`multi`), it spans the pane's full width and — together with the
/// leaf's rounded card — makes each member read as a distinct, identifiable group. Reflects focus by
/// colour (accent + full-strength text when focused, muted otherwise), the pane's selection signal.
private struct WorkroomSplitGroupTitleBar: View {
  let projectLabel: String
  let workroomName: String?
  let focused: Bool
  let isMissing: Bool
  let onClose: () -> Void
  private let theme = ThemeService.shared

  var body: some View {
    HStack(spacing: 6) {
      // Leading glyph mirrors the workroom tab chip's cube; accent on the focused member, muted else.
      Image(systemName: "cube")
        .font(.system(size: 10))
        .foregroundStyle(focused ? theme.tokens.accent : theme.tokens.fgMuted)
      if isMissing {
        Image(systemName: "exclamationmark.triangle.fill")
          .font(.system(size: 10))
          .foregroundStyle(.orange)
          .help("Directory not found")
      }
      // `project / workroom`, same format and size as `WorkroomTabChip`. Full-strength on the focused
      // member, muted otherwise — the brighter header is the in-content "this is the active pane" cue.
      HStack(alignment: .firstTextBaseline, spacing: 4) {
        Text(projectLabel)
          .foregroundStyle(focused ? Color.primary : theme.tokens.fgMuted)
        if let workroomName {
          Text("/").foregroundStyle(.tertiary)
          Text(workroomName)
            .foregroundStyle(focused ? Color.primary : theme.tokens.fgMuted)
        }
      }
      .font(.subheadline)
      .lineLimit(1)
      Spacer(minLength: 8)
      CloseWorkroomPaneButton(action: onClose)
    }
    // Trailing inset is tighter than the leading so the remove-from-split ✕ sits closer to the group's
    // right edge (the button carries its own 8pt hit padding).
    .padding(.leading, 10)
    .padding(.trailing, 4)
    .frame(height: 28)
    .frame(maxWidth: .infinity)
    // No own background and no bottom rule — inherit the card's raised lighter fill (issue #110) so the
    // header and the terminal body below read as one continuous surface.
    // So a tap/drag on the bar's empty area is hit-tested: a tap bubbles to the leaf's focus tap and a
    // drag (handled by the leaf's gesture on this bar) moves the group; the ✕ consumes its own click.
    .contentShape(Rectangle())
    .accessibilityElement(children: .contain)
    .accessibilityIdentifier("workroom.pane.titlebar")
    .accessibilityLabel(
      Text(workroomName.map { "\(projectLabel), workroom \($0)" } ?? projectLabel)
    )
  }
}

/// A draggable divider that writes a new ratio for one split node. A near-twin of `PaneTreeView`'s
/// private `SplitDivider` (kept separate so the terminal renderer stays untouched), reusing the shared
/// `PaneTreeLayout.clampRatio`/`dividerThickness` math. Unlike `SplitDivider` it draws **no** separator
/// rule — each workroom pane already has its own rounded border, so a line in the gap would double up;
/// this is just the (invisible) resize hit-zone, surfaced only by the resize cursor on hover.
private struct WorkroomSplitDivider: View {
  let orientation: SplitOrientation
  let ratio: CGFloat
  let total: CGFloat
  let onRatio: (CGFloat) -> Void
  @State private var startRatio: CGFloat?

  var body: some View {
    Rectangle()
      .fill(Color.secondary.opacity(0.0001))
      .contentShape(Rectangle())
      .gesture(
        DragGesture(coordinateSpace: .global)
          .onChanged { value in
            let start = startRatio ?? ratio
            if startRatio == nil { startRatio = start }
            let usable = max(1, total - PaneTreeLayout.dividerThickness)
            let delta =
              orientation == .horizontal ? value.translation.width : value.translation.height
            onRatio(
              PaneTreeLayout.clampRatio(start + delta / usable, total: total, along: orientation))
          }
          .onEnded { _ in startRatio = nil }
      )
      .onHover { inside in
        if inside {
          (orientation == .horizontal ? NSCursor.resizeLeftRight : NSCursor.resizeUpDown).push()
        } else {
          NSCursor.pop()
        }
      }
      .accessibilityElement()
      .accessibilityIdentifier("workroom.pane.divider")
      .accessibilityLabel(
        orientation == .horizontal ? "Vertical workroom divider" : "Horizontal workroom divider"
      )
      .accessibilityValue("\(Int((ratio * 100).rounded()))%")
      .accessibilityAdjustableAction { direction in
        let step: CGFloat = 0.05
        switch direction {
        case .increment:
          onRatio(PaneTreeLayout.clampRatio(ratio + step, total: total, along: orientation))
        case .decrement:
          onRatio(PaneTreeLayout.clampRatio(ratio - step, total: total, along: orientation))
        @unknown default: break
        }
      }
  }
}

import AppKit
import SwiftUI

/// Layout constants for the custom title bar. The bar is drawn as the top strip of the window's
/// (full-size) content rather than in an `NSTitlebarAccessoryViewController` — a leading accessory
/// is clamped to the native ~32pt title-bar height and can't be made taller (verified), so the
/// Chrome/Arc approach is used instead: `.fullSizeContentView` + draw the bar in content at any
/// height. Tune `height` to taste.
enum WorkroomTitlebar {
  /// Standard title-bar height. The custom bar is now a `.left` titlebar accessory, which AppKit
  /// clamps to the standard title-bar height; this constant is used as the reorder-vs-drop threshold
  /// in `RootView.workroomChipLocal` (a chip drag staying within the bar strip is a reorder). ~28pt.
  static let height: CGFloat = 28
  /// Leading inset so the bar's first control clears the traffic-light cluster.
  static let trafficLightInset: CGFloat = 80
}

/// A transparent backing view that lets a click-drag on the empty parts of the custom title bar
/// move the window — the content area isn't window-draggable by default (only the real title bar
/// is), so the bar needs this to stay draggable. Interactive controls drawn on top consume their
/// own clicks; clicks that fall through to this view start a window drag.
struct WindowDragBackground: NSViewRepresentable {
  func makeNSView(context: Context) -> NSView { DragView() }
  func updateNSView(_ nsView: NSView, context: Context) {}

  final class DragView: NSView {
    override var mouseDownCanMoveWindow: Bool { true }
    override func mouseDown(with event: NSEvent) {
      // Double-click on the empty bar runs the system title-bar action (zoom/minimize); a single
      // click-drag moves the window.
      if event.clickCount == 2 {
        window?.performZoom(nil)
      } else {
        window?.performDrag(with: event)
      }
    }
  }
}

/// Toggles the window's `isMovable` to gate AppKit's automatic title-bar drag. The custom title bar
/// (issue #23) is drawn in the window's full-size content, where AppKit's title-bar drag ignores the
/// content views' `mouseDownCanMoveWindow` (verified) — so a drag anywhere in the bar, including on a
/// workroom tab chip, moves the whole *window* and steals the chip's reorder `DragGesture`. `isMovable`
/// is the one lever that actually disables that drag, but it's window-wide, so we flip it by hover:
/// the bar passes `movable = false` only while the cursor is over (or dragging) a chip, and `true`
/// otherwise — so the chips reorder while the empty bar still drags the window. Hover fires before the
/// press, so the flag is already set when the drag begins.
struct WindowMovableController: NSViewRepresentable {
  let movable: Bool

  func makeNSView(context: Context) -> NSView {
    let view = NSView(frame: .zero)
    DispatchQueue.main.async { [weak view] in view?.window?.isMovable = movable }
    return view
  }

  func updateNSView(_ nsView: NSView, context: Context) {
    nsView.window?.isMovable = movable
  }
}

/// The single unified title-bar toolbar, split into a leading and a trailing half hosted as
/// `NSTitlebarAccessoryViewController`s (see `TitlebarAccessory`). They sit in the window's *one*
/// title-bar row — the leading half right after the traffic lights, the trailing half at the
/// window's true trailing edge — so together they span the full width with the draggable title-bar
/// gap between them.
///
/// Why accessories rather than `.toolbar`: SwiftUI's `.toolbar` placement is column-scoped in a
/// `NavigationSplitView` (`.primaryAction` docks to a column, not the window edge), and `.toolbar`
/// items render with the framework's own chrome. Hosting plain SwiftUI `HStack`s in title-bar
/// accessories instead gives every control one shared `.borderless` style and exact placement,
/// independent of the split's columns.

/// A hairline group separator shared by the title-bar bars.
struct TitlebarDivider: View {
  private let theme = ThemeService.shared

  var body: some View {
    Rectangle()
      .fill(theme.tokens.border)
      .frame(width: 1, height: 14)
      .padding(.horizontal, 4)
  }
}

/// Leading title-bar controls: sidebar toggle + history nav (issue #26). Our
/// own sidebar toggle (leftmost, right after the traffic lights) replaces NavigationSplitView's auto
/// one. `.toolbar(removing:)` is meant to drop it, but doesn't fully take, so the window toolbar is
/// hidden outright in `WindowBackgroundThemer` to kill its "more toolbar items" overflow chevron.
struct LeadingTitlebarBar: View {
  @EnvironmentObject var store: AppStore

  var body: some View {
    HStack(spacing: 6) {
      Button {
        store.sidebarVisible.toggle()
      } label: {
        Image(systemName: "sidebar.left")
      }
      .help(store.sidebarVisible ? "Hide sidebar (⌃⌘S)" : "Show sidebar (⌃⌘S)")
      .accessibilityLabel("Toggle sidebar")
      .accessibilityIdentifier("toolbar.toggleSidebar")
      // Hovering this button (while the sidebar is collapsed) peeks the sidebar via the edge-reveal
      // overlay (issue #74) — the trigger is the button alone, never the toolbar strip that used to
      // sit above the workroom tabs. Only report while collapsed so a hover with the sidebar pinned
      // doesn't churn reveal state.
      .onHover { hovering in
        if !store.sidebarVisible { store.hoveringLeftToggle = hovering }
      }

      TitlebarDivider()

      Button {
        store.navigateBack()
      } label: {
        Image(systemName: "chevron.left")
      }
      .help("Back (⌘[)")
      .accessibilityLabel("Back")
      .disabled(!store.canGoBack)

      Button {
        store.navigateForward()
      } label: {
        Image(systemName: "chevron.right")
      }
      .help("Forward (⌘])")
      .accessibilityLabel("Forward")
      .disabled(!store.canGoForward)
    }
    .buttonStyle(ToolbarIconButtonStyle())
    .padding(.horizontal, 10)
    // The titlebar accessory host is the full title-bar height (52pt — NOT 28), and NSHostingView
    // top-aligns a fixed-height root inside it, so the icons sat high. Fill the host and let the HStack
    // centre its buttons on the traffic-light line (the close button centres at y=26 of the 52pt host).
    .frame(maxHeight: .infinity)
  }
}

/// Trailing title-bar controls: the quick terminal (issue #39) and the selected target's run/open-in
/// actions (issue #7). (Notifications + inspector visibility now live in the activity bar, so no bell
/// or toggle here.) `RunControls`/`OpenInControl` render nothing when not applicable, so the group
/// collapses to just the quick terminal in the empty state.
struct TrailingTitlebarBar: View {
  @EnvironmentObject var store: AppStore
  @EnvironmentObject var updater: Updater

  var body: some View {
    HStack(spacing: 6) {
      // A newer version is waiting (Sparkle gentle reminder) — the accent pill leads the trailing
      // controls. Self-hides when no update is pending; the divider matches. It lives here, not in the
      // leading bar, because there it overran the sidebar and sat on the NavigationSplitView's
      // sidebar/detail divider, whose full-height resize grab zone stole the cursor (and a drag
      // resized the sidebar). At the window's trailing edge it's nowhere near that divider.
      if updater.availableVersionString != nil {
        UpdateAvailableButton()
        TitlebarDivider()
      }

      // The selected target's open-in + run actions (a group). Open In leads it, swapped with the
      // Quick Terminal that used to sit here — Quick Terminal now trails at the window edge.
      if let target = store.selectedTarget, !target.isMissing {
        OpenInControl(path: target.path)
        if let projectPath = AppStore.projectPath(of: store.selectedTargetID) {
          RunControls(target: target, projectPath: projectPath)
        }
        // Separate the target's actions from the always-present quick terminal — a different group.
        TitlebarDivider()
      }

      // Quick Terminal (⌥§) — a ~/ shell in its own window. Always present; sits at the window's
      // trailing edge, after the target's run/open-in actions.
      Button {
        NotificationCenter.default.post(name: .showQuickTerminal, object: nil)
      } label: {
        // The `.badge.plus` extends this glyph's box upward, so a plain centre sits ~0.5pt high vs the
        // other icons; nudge it down to sit on the same line.
        Image(systemName: "macwindow.badge.plus")
          .offset(y: 0.5)
      }
      .help("Quick Terminal (⌥§)")
      .accessibilityLabel("Quick Terminal")
      .accessibilityIdentifier("toolbar.quickTerminal")
    }
    .buttonStyle(ToolbarIconButtonStyle())
    // Trailing gap so the last control isn't flush to the window edge (previously supplied by the
    // removed TitlebarControlsBar — the right-sidebar toggle it hosted is redundant with the activity
    // bar, whose section icons show/collapse the inspector).
    .padding(.trailing, 10)
    // Fill the full-height (52pt) accessory host so the HStack centres its buttons — see LeadingTitlebarBar.
    .frame(maxHeight: .infinity)
  }
}

