import AppKit
import Defaults
import SwiftUI

/// The "Open in…" editor control for a selected target: a menu whose primary action reopens in the
/// last-picked editor. A plain `View` (not `ToolbarContent`) so it composes into the title-bar
/// toolbar (`TrailingTitlebarBar`) as a sibling of the other controls, sharing its `.borderless`
/// button style. (Renders nothing when no editors are installed.)
struct OpenInControl: View {
  let path: String

  /// Bundle id of the last editor picked from the "Open in…" menu — the primary action reopens in it.
  @Default(.lastEditor) private var lastEditorID

  var body: some View {
    let editors = ExternalEditor.installed
    if !editors.isEmpty {
      let remembered = editors.first { $0.id == lastEditorID } ?? editors[0]
      // Two SEPARATE controls in one tight group: an icon Button that opens in the remembered editor
      // on a single click (also ⇧⌘O / the Go-menu item), and a chevron Menu to pick a different one.
      // Both inherit the bar's `ToolbarIconButtonStyle`, so each gets its own hover well. Negative
      // spacing pulls the two 22pt-min wells together so the small chevron sits snug against the icon
      // (each well only paints on its own hover, so the slight overlap never shows two at once).
      HStack(spacing: -8) {
        Button {
          remembered.open(path)
        } label: {
          Image(systemName: "arrow.up.forward.app")
            .hidden()
            .overlay {
              Image(nsImage: remembered.icon).renderingMode(.original).resizable().scaledToFit()
            }
            .frame(width: 16, height: 16)
        }
        .help("Open in \(remembered.name) (⇧⌘O)")
        .accessibilityLabel("Open in \(remembered.name)")

        Menu {
          ForEach(editors) { editor in
            Button {
              lastEditorID = editor.id
              editor.open(path)
            } label: {
              Label {
                Text(editor.name)
              } icon: {
                Image(nsImage: editor.icon).renderingMode(.original)
              }
            }
          }
        } label: {
          Image(systemName: "chevron.down")
            .font(.system(size: 8, weight: .semibold))
            .foregroundStyle(.secondary)
        }
        .menuStyle(.button)
        // We draw the chevron ourselves, so hide the system disclosure indicator.
        .menuIndicator(.hidden)
        .fixedSize()
        .help("Open in… (choose editor)")
        .accessibilityLabel("Choose editor")
      }
    }
  }
}

/// The run-command controls for a selected workroom (issue #7): a Run button that becomes Stop +
/// Restart while the command is running. Renders nothing when the project has no run command
/// configured (no disabled ghost). Reads run-state straight off `AppStore` — `@EnvironmentObject`
/// re-evaluates on `@Published` changes, so the toggle flips live (OV-A). A plain `View` (not
/// `ToolbarContent`) so it composes into the title-bar toolbar (`TrailingTitlebarBar`).
struct RunControls: View {
  let target: TerminalTarget
  /// The owning project's path — used to look up the configured command (`hasRunCommand`).
  let projectPath: String
  @EnvironmentObject var store: AppStore

  var body: some View {
    if store.canRunCommand(for: target, inProject: projectPath) {
      if store.isRunCommandRunning(for: target.id) {
        Button {
          store.stopRunCommand(for: target)
        } label: {
          Image(systemName: "stop.fill")
        }
        .help("Stop the run command (⇧⌘R) — again to force-quit")
        .accessibilityLabel("Stop")
        .accessibilityIdentifier("runCommand.stop")

        Button {
          store.restartRunCommand(for: target)
        } label: {
          Image(systemName: "arrow.clockwise")
        }
        .help("Restart the run command (⌥⌘R)")
        .accessibilityLabel("Restart")
        .accessibilityIdentifier("runCommand.restart")
      } else {
        // Not running (no run tab, or stopped-but-open). `runOrFocusRunCommand` acts on the
        // selection — which is this target — so it starts, or re-runs a stopped pane (OV-B).
        Button {
          store.runOrFocusRunCommand()
        } label: {
          Image(systemName: "play.fill")
        }
        .help("Run the project command (⌘R)")
        .accessibilityLabel("Run")
        .accessibilityIdentifier("runCommand.run")
      }
    }
  }
}

import SwiftUI

/// The detail pane's terminals for one target (a workroom or a project root): a horizontal
/// tab strip below the title bar plus the active terminal. Observes `TerminalSessions` so
/// adding, closing, and switching tabs all update live.
///
/// This view coordinates the tab strip (`TerminalTabStrip`) and the pane content
/// (`PaneTreeView`), owning the cross-component drag-into-pane wiring: `chipPaneDrag` (the live
/// drop preview the pane tree renders) and `contentFrame` (the pane area's global rect, used to
/// tell "over the strip" reorder from "over a pane" drop-to-split and to localise the cursor).
/// The strip is handed those via a binding plus the `chipLocal`/`chipDropTarget` closures.
struct WorkroomTerminalsView: View {
  let target: TerminalTarget
  @ObservedObject var sessions: TerminalSessions
  /// Whether this workroom's terminal may hold keyboard focus — `false` for a co-displayed but
  /// non-focused split member, so it doesn't steal first responder (and the workroom selection) on mount.
  var surfaceActive: Bool = true
  /// A workroom-split member (issue #110) draws the terminal with a tighter gutter to its group card,
  /// so the lighter group fill reads as a thin frame, not a wide margin. Solo targets keep the wider
  /// gutter that lines the terminal up with the sidebar cards.
  var compact: Bool = false
  @EnvironmentObject var notifications: NotificationCenterStore
  @EnvironmentObject var store: AppStore
  @Environment(\.accessibilityReduceMotion) private var reduceMotion

  // Drag a tab chip down into a pane to split (issue #3). `chipPaneDrag` is the live drop preview
  // (content-local), shown by `PaneTreeView`; `contentFrame` is the pane area's global rect, used to
  // tell "over the strip" (reorder) from "over a pane" (drop-to-split) and to localise the cursor.
  @State private var chipPaneDrag: PaneDragState?
  @State private var contentFrame: CGRect = .zero

  var body: some View {
    let tabs = sessions.tabs(for: target)
    let active = sessions.activeTab(for: target)
    // The terminal (or empty state) fills the pane; the tab bar rides on safeAreaInset so it only
    // ever takes its natural height — otherwise the tab bar's horizontal ScrollView grabs the
    // vertical slack when there's no terminal below it and balloons.
    Group {
      if let active {
        // Always render through the one pane tree — a solo terminal is just a single-leaf layout.
        // Routing solo and split through the SAME host means a surface has exactly one owner; an
        // earlier split→solo bug came from two `TerminalContainerView`s (the solo branch and the dying
        // split leaf) fighting over the same surface and stranding it in a detached container (#3).
        PaneTreeView(
          layout: contentLayout(active: active), target: target, sessions: sessions,
          externalDrag: chipPaneDrag, surfaceActive: surfaceActive
        )
        .background(
          GeometryReader { geo in
            Color.clear.preference(key: ContentFrameKey.self, value: geo.frame(in: .global))
          }
        )
        // Solo: 6pt gutter left/right; the bottom uses 4pt so the terminal pane's bottom edge lines up
        // with the left/right sidebar cards — the detail content carries a little extra bottom inset of
        // its own, so a 6pt gutter sat ~2pt high vs the sidebars (measured). A split member (`compact`,
        // issue #110) tightens this to a thin 2pt frame inside its group card. Top is always 0 so the
        // tab strip sits flush on the content (the active tab bridges the panel→bg colour step) — the
        // Chrome-style merge with the strip above.
        .padding(.horizontal, compact ? 2 : 6)
        .padding(.bottom, compact ? 2 : 4)
        .padding(.top, 0)
      } else {
        ContentUnavailableView {
          Label("No terminal", systemImage: "terminal")
        } description: {
          Text("Open one with ⌘T.")
        } actions: {
          Button("New Terminal") { sessions.addTab(for: target) }
            .buttonStyle(.borderedProminent)
            // Use the active theme accent rather than the system blue (issue #36).
            .tint(ThemeService.shared.tokens.accent)
            .accessibilityIdentifier("NewTerminal")
        }
      }
    }
    .frame(maxWidth: .infinity, maxHeight: .infinity)
    .onPreferenceChange(ContentFrameKey.self) { contentFrame = $0 }
    .safeAreaInset(edge: .top, spacing: 0) {
      // No tab bar when there are no terminals: the empty state's "New Terminal" button (and ⌘T) cover
      // adding one, so the strip and its "+" would be redundant. A split member's remove-from-split ✕
      // now lives in its group title bar (issue #110), drawn by the leaf above this view and present
      // even with zero tabs — so the strip no longer needs to stay alive just to host the ✕.
      if !tabs.isEmpty {
        TerminalTabStrip(
          tabs: tabs, activeID: active?.id, target: target, sessions: sessions,
          compact: compact,
          chipPaneDrag: $chipPaneDrag,
          localize: { chipLocal($0) },
          dropTarget: { chipDropTarget(at: $0) }
        )
        // A backgrounded workroom (`!surfaceActive` — a non-focused workroom *split* member, or a
        // backgrounded solo workroom, issue #82) dims its terminals via the per-pane scrim in
        // `PaneTreeView`. That scrim covers only the Metal surfaces, not this tab strip — it rides on
        // the safe-area inset, outside the pane tree — so without this the strip stayed bright while
        // its panes faded. The strip is plain SwiftUI (no Metal layer), so a plain `.opacity` fade is
        // enough; match the scrim's `surfaceActive` animation so the strip and panes fade together.
        .opacity(surfaceActive ? 1 : 0.45)
        .animation(reduceMotion ? nil : .easeInOut(duration: 0.07), value: surfaceActive)
      }
    }
    // Create the first terminal once the pane appears (and for each new target), then reconcile
    // occlusion so the right surfaces render after a target switch (issue #3).
    .task(id: target.id) {
      // Through the store so a pending auto-run (issue #7) suppresses the default first tab and the
      // run command becomes tab #1 instead of being orphaned beside a stray "Terminal 1".
      store.ensureInitialTerminal(for: target)
      sessions.reconcileOcclusion(for: target)
    }
    // Focusing a terminal dismisses its notifications — but ONLY while this view is the focused one
    // (`surfaceActive`). In a workroom split EVERY member renders through this view, including
    // co-displayed NON-focused members (`surfaceActive: false`, issue #23); without the gate, such a
    // member would wipe its OWN notifications on mount/remount via the `initial: true` fire — a pane
    // you're explicitly not looking at (issue #89). With the gate: for the focused member, `active.id`
    // changing *is* a focus change (chip tap, ⌘1–9, sidebar switch, close revealing a neighbour) and
    // `initial` handles its first appearance. The sibling `surfaceActive` hook covers selection
    // MOVING to a member — `selectedTargetID` changes but the member's `active.id` does not, so the
    // hook above wouldn't fire. In the single-workroom path `surfaceActive` is always true, so this
    // behaves exactly as before. Returning to the app with the same tab focused is handled separately
    // by RootView's didBecomeActive → dismissFocusedTerminalNotifications.
    .onChange(of: active?.id, initial: true) { _, id in
      if surfaceActive, let id { notifications.dismiss(tab: id) }
    }
    .onChange(of: surfaceActive) { _, nowFocused in
      if nowFocused, let id = active?.id { notifications.dismiss(tab: id) }
    }
    // All three AND in `!store.hasModalPresentation` for the same reason RootView's booleans do: a
    // menu key equivalent still fires while a dialog or sheet is up, so ⌘W / ⌘F / ⌘↑ / ⌘↓ / ⌘D would
    // otherwise act on the terminal behind it. Disabling the item drops the key equivalent.
    //
    // Drive the "Close Terminal" menu command's enabled state.
    .focusedSceneValue(\.hasTerminal, !tabs.isEmpty && !store.hasModalPresentation)
    // Drive the Go-menu Previous/Next Terminal Tab items (issue #29) — only meaningful with ≥2 tabs.
    .focusedSceneValue(\.multipleTerminalTabs, tabs.count > 1 && !store.hasModalPresentation)
    // Drive View ▸ "Resize Splits Evenly" (issue #83) — only when a terminal split is on screen. This
    // view mounts only in the single-workroom path and only once a blocking setup script clears, so
    // the item can never act on a hidden split.
    .focusedSceneValue(
      \.terminalSplitVisible,
      sessions.isSplitVisible(for: target) && !store.hasModalPresentation)
  }

  /// The layout the content area renders: the split when it's visible, else the focused solo tab.
  private func contentLayout(active: TerminalTab) -> TerminalPaneLayout {
    sessions.isSplitVisible(for: target)
      ? (sessions.split(for: target) ?? .leaf(active.id)) : .leaf(active.id)
  }

  /// The content-local point for a chip drag at `global`, or nil when the cursor is outside the pane
  /// area (i.e. still over the strip → a reorder, not a drop-into-pane).
  private func chipLocal(_ global: CGPoint) -> CGPoint? {
    guard contentFrame.contains(global) else { return nil }
    return CGPoint(x: global.x - contentFrame.minX, y: global.y - contentFrame.minY)
  }

  /// Where a chip dropped at `global` lands (pane + edge), using the same pane plan the renderer uses,
  /// or nil if it isn't over a pane.
  private func chipDropTarget(at global: CGPoint) -> (tab: TerminalTab.ID, edge: PaneEdge)? {
    guard let local = chipLocal(global), let active = sessions.activeTab(for: target) else {
      return nil
    }
    let plan = PaneTreeLayout.plan(
      contentLayout(active: active), in: CGRect(origin: .zero, size: contentFrame.size))
    return PaneTreeLayout.dropTarget(at: local, panes: plan.panes)
  }
}

/// The pane area's global frame — lets the strip localise a chip drag and tell "over the strip"
/// (reorder) from "over a pane" (drop-to-split).
private struct ContentFrameKey: PreferenceKey {
  static var defaultValue: CGRect = .zero
  static func reduce(value: inout CGRect, nextValue: () -> CGRect) {
    let next = nextValue()
    if next != .zero { value = next }
  }
}

import Defaults
import SwiftUI

/// The horizontal tab strip above a target's terminal: a chip per terminal tab, a "+" to open a
/// new one, and the drag interactions — reorder within the strip, or drag a chip down into a pane
/// to split (issue #3). Fully owns the reorder drag state; the drop-into-pane wiring is shared with
/// the pane content, so `WorkroomTerminalsView` passes a `chipPaneDrag` binding (the live preview the
/// pane tree renders) plus `localize`/`dropTarget` closures that resolve a cursor point against the
/// pane area (which only the coordinator knows the frame of).
///
/// The "+" is **adaptive** (issue #129): while the tabs fit it sits inline, hugging the last chip;
/// once they overflow it lifts out of the scroller and pins at the strip's trailing edge, so it's
/// never scrolled out of reach. The scroller's trailing edge carries an alpha ramp in that state, so
/// a clipped chip dissolves instead of being cut mid-glyph. The decision itself is
/// `TabStripOverflow.pinsControls`, wired up by the shared `OverflowingTabScroller` (which
/// `WorkroomTabBar` uses too, so the two strips can't drift).
struct TerminalTabStrip: View {
  let tabs: [TerminalTab]
  let activeID: TerminalTab.ID?
  let target: TerminalTarget
  @ObservedObject var sessions: TerminalSessions
  /// In a workroom-split group (issue #110) the strip tightens its leading inset so the leftmost tab
  /// lines up with the left edge of the group's terminal panel below it. Default (solo) keeps 8pt.
  var compact: Bool = false
  @EnvironmentObject var store: AppStore
  @EnvironmentObject var notifications: NotificationCenterStore
  @EnvironmentObject var agentManager: TerminalAgentManager
  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  /// The tab whose ✦ agent popover is open.
  @State private var agentPopoverTab: TerminalTab.ID?
  /// Global default diff layout — the toolbar's mode toggle shows it as active until this tab gets a
  /// per-tab override (`TerminalTab.diffViewModeOverride`).
  @Default(.diffViewMode) private var defaultDiffViewMode

  /// The live drop-into-pane preview, shared with `PaneTreeView` via the coordinator.
  @Binding var chipPaneDrag: PaneDragState?
  /// The pane-local point for a chip drag at a global location, or nil when the cursor is still over
  /// the strip (→ a reorder, not a drop-into-pane). Owned by the coordinator (needs the pane frame).
  let localize: (CGPoint) -> CGPoint?
  /// Where a chip dropped at a global location lands (pane + edge), or nil if it isn't over a pane.
  let dropTarget: (CGPoint) -> (tab: TerminalTab.ID, edge: PaneEdge)?

  @State private var hoveredTab: TerminalTab.ID?
  @State private var addHovering = false
  /// The last chip click (id + time), so a quick second click on the same chip promotes a preview
  /// content tab to persisted without delaying the eager first-click select (#66).
  @State private var lastChipClick: ChipClick?

  // Drag-to-reorder. The tab order is *frozen* for the duration of a drag: the dragged
  // chip simply follows the cursor (its slot never moves, so it can't jump), and the
  // other chips slide aside to open a gap. The reorder is committed once, on drop.
  @State private var draggingID: TerminalTab.ID?
  @State private var dragTranslation: CGFloat = 0
  @State private var widths: [TerminalTab.ID: CGFloat] = [:]

  private let tabSpacing: CGFloat = 4
  /// The strip's own right inset. Lives here rather than on `tabToolbar` (which renders *nothing* when
  /// there's no active tab) so a pinned "+" is never flush against the pane edge.
  private static let stripTrailingInset: CGFloat = 4

  /// The strip's leading inset: in a workroom-split group the leftmost tab lines up with the group's
  /// terminal panel below (issue #110); solo keeps 8pt.
  private var leadingInset: CGFloat { compact ? 4 : 8 }

  var body: some View {
    // Resolve the drag once per layout: which tab is dragging, and where it would land.
    let draggedIndex = draggingID.flatMap { id in tabs.firstIndex { $0.id == id } }
    // While dragging a chip down into a pane, the strip stops opening a reorder gap.
    let dropIndex =
      chipPaneDrag != nil ? nil : draggedIndex.map { dropTargetIndex(tabs, draggedIndex: $0) }
    let draggedWidth = draggingID.flatMap { widths[$0] } ?? 0
    // Members of the split group (≥2), so a grouped chip's selected pill can inset itself to sit
    // *inside* the `splitWell` bracket rather than overrunning it.
    let groupMembers = splitMemberSet

    HStack(spacing: 0) {
      // The scrolling chips plus the adaptive "+" (issue #129), assembled by the shared
      // `OverflowingTabScroller`. The width it measures for the overflow predicate is the scroller's
      // own: it's the flexible child beside the `fixedSize` toolbar, so it already equals "strip minus
      // toolbar" (and the full strip when there's no active tab and the toolbar renders nothing).
      OverflowingTabScroller(
        leadingInset: leadingInset, spacing: tabSpacing,
        inlineLead: TabStripMetrics.inlineAddLead,
        // Scroll the focused tab into view on selection (issue #129 follow-up); suspended mid-drag,
        // like the reorder gap animation below.
        scrollTarget: activeID, scrollSuspended: draggingID != nil
      ) { overflowing in
        chipRun(
          tabs, draggedIndex: draggedIndex, dropIndex: dropIndex, draggedWidth: draggedWidth,
          groupMembers: groupMembers, overflowing: overflowing)
      } controls: {
        addTerminalButton
      }
      // Per-current-tab actions (issue #72), pinned to the strip's right edge as a fixed-size layout
      // sibling of the scrolling tabs — so the chip area yields first in a cramped split pane and the
      // toolbar never overlaps the chips. An overflowing strip's "+" now sits between the two, pinned
      // to the scroller's trailing edge (issue #129). The remove-from-split ✕ used to sit to its
      // right; it now lives in the workroom-split group title bar (issue #110).
      tabToolbar
    }
    // No top padding: the strip sits flush at the top of the detail pane so the terminal tabs align
    // with the top of the sidebar (the pane's own top inset is dropped too — see `WorkroomPaneLeaf`).
    .padding(.top, 0)
    // Flush with the content below — the active tab's `bg` fill bridges the panel→bg colour step so
    // the strip reads as part of the terminal panel (Chrome-style). No bottom gap.
    .padding(.bottom, 0)
    .padding(.trailing, Self.stripTrailingInset)
  }

  /// The chips themselves plus the hairline that sets the inline "+" apart — everything that scrolls
  /// and stays put across an overflow flip. Measured as one run for the overflow predicate (by
  /// `OverflowingTabScroller`, which also lays the row out with the leading inset: in a split group the
  /// leftmost tab lines up with the group's terminal panel below — 4pt compact gutter, issue #110 —
  /// while solo keeps the 8pt inset). The split bracket is drawn behind it (leading-aligned, so x = 0
  /// is the first chip's leading edge, which is what `splitRunRect` computes against).
  @ViewBuilder
  private func chipRun(
    _ tabs: [TerminalTab], draggedIndex: Int?, dropIndex: Int?, draggedWidth: CGFloat,
    groupMembers: Set<TerminalTab.ID>, overflowing: Bool
  ) -> some View {
    HStack(spacing: tabSpacing) {
      ForEach(Array(tabs.enumerated()), id: \.element.id) { index, tab in
        let isDragging = draggingID == tab.id
        let isHovered = hoveredTab == tab.id && draggingID == nil
        // Activity in an unfocused tab highlights the tab itself (accent title + faint accent
        // fill) instead of a count — a tab is too narrow for a number.
        let hasActivity = notifications.count(tab: tab.id) > 0
        // Run-command state for this tab's chip icon (issue #7): only the dedicated run tab
        // carries one — running (green) vs failed (red octagon, #79) vs stopped/exited (dim).
        // Process-based, distinct from the OSC-9;4 RunningUnderline below.
        let runState: TerminalTabChip.RunState? =
          store.runTabID(for: target.id) == tab.id
          ? (store.isRunCommandRunning(for: target.id)
            ? .running : (store.runFailed(for: target.id) ? .failed : .stopped))
          : nil
        // Dragged chip tracks the cursor; the rest shift to open the gap.
        let offsetX =
          isDragging
          ? dragTranslation
          : gapShift(
            for: index, draggedIndex: draggedIndex, target: dropIndex,
            amount: draggedWidth + tabSpacing)
        // A ✦ badge marks any tab with a live diagnosis (issue #49) — the per-tab signal that
        // complements the active tab's diagnosis shown in the detail-panel status bar.
        let agentBadge = agentManager.banners[tab.id] != nil
        TerminalTabChip(
          tab: tab, isActive: tab.id == activeID, isHovered: isHovered,
          isDragging: isDragging, hasActivity: hasActivity, runState: runState,
          showLeadingSeparator: showsLeadingSeparator(at: index),
          isGrouped: groupMembers.contains(tab.id),
          agentBadge: agentBadge, onAgentTap: { agentPopoverTab = tab.id }
        ) {
          store.requestCloseTerminalTab(tab.id, for: target)
        }
        .popover(
          isPresented: Binding(
            get: { agentPopoverTab == tab.id },
            set: { if !$0 { agentPopoverTab = nil } })
        ) {
          agentPopover(for: tab)
        }
        .onHover { inside in
          if inside { hoveredTab = tab.id } else if hoveredTab == tab.id { hoveredTab = nil }
        }
        .onTapGesture {
          // Eager: select on the first click (changes `active.id`; the view's .onChange hook
          // marks the tab read). A quick second click on the same chip promotes a preview content
          // tab to persisted (#66) — `persist` no-ops on terminal/persisted tabs, so this is safe
          // for every chip and never delays the select.
          let now = Date()
          sessions.select(tab.id, for: target)
          if let last = lastChipClick, last.id == tab.id, now.timeIntervalSince(last.at) < 0.35 {
            sessions.persist(tab.id, for: target)
            lastChipClick = nil
          } else {
            lastChipClick = ChipClick(id: tab.id, at: now)
          }
        }
        .tabChipContextMenu(tab: tab, target: target, store: store, sessions: sessions)
        // Measure in .global space: a .local drag reads coordinates relative to the
        // chip, which itself moves via .offset(dragTranslation) — that feedback loop
        // dampens the translation so the chip lags the cursor. Global space is fixed.
        .gesture(
          DragGesture(minimumDistance: 6, coordinateSpace: .global)
            .onChanged { value in
              if draggingID == nil { draggingID = tab.id }
              guard draggingID == tab.id else { return }
              dragTranslation = value.translation.width
              // Dragged down over the pane area → preview a drop-into-pane (the strip stops gapping).
              chipPaneDrag = localize(value.location)
                .map { PaneDragState(tabID: tab.id, location: $0) }
            }
            .onEnded { value in
              if let drop = dropTarget(value.location) {
                sessions.moveTabIntoSplit(
                  tab.id, ontoEdge: drop.edge, of: drop.tab, for: target)
                draggingID = nil
                dragTranslation = 0
              } else {
                commitDrag()  // a plain strip reorder
              }
              chipPaneDrag = nil
            }
        )
        .offset(x: offsetX)
        .zIndex(isDragging ? 1 : 0)
        .animation(
          isDragging || reduceMotion ? nil : .easeInOut(duration: 0.18), value: offsetX
        )
        // Scroll target for `OverflowingTabScroller`'s `ScrollViewReader` (issue #129 follow-up) — the
        // same id `ForEach` already keys identity on.
        .id(tab.id)
      }
      // A divider sets the new-terminal (+) button apart from the last tab (mirrors the workroom
      // tab bar). Hidden when the last tab is set apart on its own — focused or hovered — to match
      // the "no divider beside the focused/hovered tab" rule above, and when the "+" has pinned
      // (issue #129): the fade and the gutter already separate the two regions, and a hairline beside
      // a dissolving edge reads as a cut. Toggled via OPACITY (not removed) so it stays laid out and
      // the "+" never shifts as the hover/focus comes and goes — which also keeps the measured run
      // width stable across those transitions.
      // Only present at all with ≥1 tab (a split member's empty strip is just the "+" and close ✕).
      // Negative leading trims the gap to the last tab to ~2pt (HStack `tabSpacing` 4 − 2), matching
      // the inter-tab dividers.
      if !tabs.isEmpty {
        Rectangle()
          .fill(ThemeService.shared.tokens.border)
          .frame(width: 1, height: 14)
          .padding(.leading, -2)
          .padding(.trailing, 4)
          .opacity(showsTrailingDivider && !overflowing ? 1 : 0)
      }
    }
    .background(alignment: .leading) { splitWell(tabs) }
    .onPreferenceChange(TabWidthKey.self) { widths = $0 }
  }

  /// The "new terminal" (+) button, rendered in one of two positions (issue #129): inline as the last
  /// element of the scrolling row while the tabs fit, so it hugs the rightmost tab; or lifted out and
  /// pinned to the scroller's trailing edge once they overflow, so it can't be scrolled out of reach.
  /// The same view either way; `OverflowingTabScroller` applies its inline positioning pad and takes
  /// its width measurement, so that width stays a pure intrinsic measurement.
  private var addTerminalButton: some View {
    Button {
      sessions.addTab(for: target)
    } label: {
      Image(systemName: "plus")
        .font(.system(size: 11))
        .foregroundStyle(.secondary)
        .padding(4)
        .background(
          RoundedRectangle(cornerRadius: 5)
            .fill(ThemeService.shared.tokens.hover.opacity(addHovering ? 1 : 0))
        )
        // The whole padded glyph (the hover well's area) is clickable/hoverable, not just the "+" —
        // the transparent padding wouldn't hit-test on its own.
        .contentShape(Rectangle())
    }
    .buttonStyle(.plain)
    .onHover { addHovering = $0 }
    .help("New terminal (⌘T)")
    .accessibilityLabel("New terminal")
    .accessibilityIdentifier("NewTerminal")
  }

  /// Icon-only actions for the *current* (active) tab (issue #72): the diff view-mode toggle + "Open
  /// file in…" (diff tabs only), "Split right", and "Close all". Renders nothing when there's no
  /// active tab. `fixedSize` so it keeps its intrinsic width and the scrolling chip area yields first
  /// in a narrow split pane.
  @ViewBuilder
  private var tabToolbar: some View {
    if let active = tabs.first(where: { $0.id == activeID }) {
      HStack(spacing: 2) {
        // Diff (content) tab: the unified/side-by-side switch (issue #66) + open the working file in
        // the in-app viewer. The switch is one grouped segmented control — the active mode's
        // segment stays lit; clicking sets this tab's override (`TerminalTab.diffViewModeOverride`),
        // which the pane's `DiffViewer` re-renders to. Shows the global default until a choice is made.
        if case .diff(let descriptor) = active.content {
          DiffModeSwitch(mode: active.diffViewModeOverride ?? defaultDiffViewMode) {
            sessions.setDiffViewMode($0, forTab: active.id, in: target)
          }
          // Open the working file in the in-app viewer (issue #117). Disabled when the source was
          // deleted (review D4) — there's no working copy to open.
          TabToolbarButton(
            systemImage: "doc.text", help: "Open File",
            accessibilityLabel: "Open File", identifier: "tab.toolbar.openFile"
          ) {
            store.openFilePreview(path: descriptor.path)
          }
          .disabled(descriptor.change == .deleted)
        }
        // Markdown file tab: the source/preview switch (the toggle lifted out of the file viewer's
        // own header into the tab toolbar, alongside split). Sets this tab's
        // `markdownPreviewOverride`, which the pane's `PlainFileViewer` reads. Markdown-only —
        // other files have no rendered form, so no switch.
        if case .file(let descriptor) = active.content,
          PlainFileViewer.isMarkdown(descriptor.path)
        {
          MarkdownModeSwitch(preview: active.markdownPreviewOverride ?? true) {
            sessions.setMarkdownPreview($0, forTab: active.id, in: target)
          }
        }
        TabToolbarButton(
          systemImage: "rectangle.trailinghalf.inset.filled", help: "Split right (⌘D)",
          accessibilityLabel: "Split right", identifier: "tab.toolbar.splitRight"
        ) {
          sessions.splitTab(active.id, on: .right, for: target)
        }
        TabToolbarButton(
          systemImage: "rectangle.bottomhalf.inset.filled", help: "Split down (⇧⌘D)",
          accessibilityLabel: "Split down", identifier: "tab.toolbar.splitDown"
        ) {
          sessions.splitTab(active.id, on: .bottom, for: target)
        }
        TabToolbarButton(
          systemImage: "xmark.square", help: "Close all tabs in this workroom",
          accessibilityLabel: "Close all tabs in this workroom", identifier: "tab.toolbar.closeAll"
        ) {
          store.requestCloseAllTerminalTabs(for: target)
        }
      }
      .fixedSize()
    }
  }

  /// A rounded *outline* bracketing the split's contiguous chip run, so it's easy to see which tabs
  /// are grouped/split (issue #3). Deliberately an outline, not a filled backing: a fill occupies the
  /// same channel as the active-chip fill, so any visible strength made a grouped-but-inactive chip
  /// read as focused. The border groups without competing with selection. Hidden during a drag
  /// (group-aware strip drag is Phase 2), and only shown for a real split (≥2).
  @ViewBuilder
  private func splitWell(_ tabs: [TerminalTab]) -> some View {
    if draggingID == nil, let run = splitRunRect(tabs) {
      RoundedRectangle(cornerRadius: 7)
        .strokeBorder(ThemeService.shared.tokens.border, lineWidth: 1)
        .frame(width: run.width)
        .offset(x: run.x)
    }
  }

  /// The x-offset and width of the split members' contiguous run within the chip strip, in the chips'

/// stretched from just right of the traffic lights to the window's trailing edge (`fillsWidth`). It
/// lays out, left to right: the leading controls (sidebar toggle + history nav), then — when any
/// workroom/root has a terminal — a divider and the **workroom tab bar, which fills all the space
/// between** the leading and trailing controls; then the trailing controls (run/open-in + bell +
/// inspector toggle), hugging the right edge. One accessory rather than two because both halves can't
/// claim the trailing edge while a stretchable bar fills the middle. Env objects + the chip-drag
/// plumbing are injected/captured inside the closure because the hosted tree lives outside the
/// WindowGroup's environment.
private var titlebarBar: some View {
  let tabs = store.displayedWorkroomTargets()
  return HStack(spacing: 6) {
    LeadingTitlebarBar()
    if !tabs.isEmpty {
      WorkroomTabBar(
        tabs: tabs, selectedID: store.selectedTargetID,
        onSelect: { selectWorkroomTab($0) },
        chipPaneDrag: $workroomChipDrag,
        localize: { workroomChipLocal($0) },
        dropTarget: { workroomChipDropTarget(at: $0) }
      )
    } else {
      Spacer(minLength: 0)
    }
    TrailingTitlebarBar()
  }
  // Clear the traffic-light cluster on the leading edge (the bar now spans the full window width
  // as the top strip of the content, not an accessory placed after the lights by AppKit).
  .padding(.leading, WorkroomTitlebar.trafficLightInset)
  .frame(height: WorkroomTitlebar.height)
  .frame(maxWidth: .infinity)
  // Empty regions of the bar drag the window; the panel colour reads as one surface with the
  // title bar / tab bar / gutters (it sits behind the transparent drag layer).
  .background(WindowDragBackground())
  .background(ThemeService.shared.tokens.panel)
}

var body: some View {
  // The custom chrome lives in a full-width `.left` titlebar accessory (`accessoryBarContent`, hosted
  // via `TitlebarAccessoryHost` in `rootWindowChrome`), not a content top-strip and not SwiftUI
  // `.toolbar` items — so AppKit owns the bar height (an empty NSToolbar; see WindowBackgroundThemer)
  // and centers the traffic lights alongside the controls.
  // `rootModals` sits OUTSIDE `rootReveals` so the command-palette dialogs — which are `.overlay`s,
  // not sheets — render above the toast stack and above an edge-revealed sidebar. Inside, an
  // arriving toast drew on top of the dialog. Only the overlay presenters care about this ordering;
  // `.sheet` / `.alert` are position-independent.
  rootWindowChrome(rootLifecycle(rootModals(rootReveals(splitView))))
}

/// The full title-bar bar hosted in the `.left` titlebar accessory: leading controls, the workroom
/// tab strip (fills + scrolls), trailing controls. Environment objects are re-injected because the
/// accessory is a separate hosting tree from the main window content.
private var accessoryBarContent: some View {
  HStack(spacing: 6) {
    LeadingTitlebarBar()
    workroomTabsBar
    TrailingTitlebarBar()
  }
  .padding(.horizontal, 8)
  .frame(maxWidth: .infinity, maxHeight: .infinity)
  // No own background — the accessory is transparent so the window's panel bg shows through it AND
  // behind the traffic lights uniformly (an opaque fill here didn't match the titlebar strip behind
  // the lights). WindowBackgroundThemer sets the window bg to the panel token.
  .environmentObject(store)
  .environmentObject(notifications)
  .environmentObject(terminals)
  .environmentObject(updater)
  // The accessory is a window-level AppKit hosting tree, so the dialog's own backdrop — an overlay
  // on the content below — can never cover it. Left alone, the workroom tab strip's New/Open buttons
  // and its chips stay clickable through a "modal" dialog, and the bar stays undimmed while
  // everything beneath it darkens. Both halves read the same opacity + curve from
  // `DialogOverlayStyle` so they can't drift.
  .disabled(store.activePicker != nil)
  .overlay {
    Color.black
      .opacity(
        store.activePicker != nil ? DialogOverlayStyle.backdropOpacity(for: colorScheme) : 0
      )
      .allowsHitTesting(false)
  }
  .animation(
    reduceMotion ? nil : DialogOverlayStyle.revealAnimation, value: store.activePicker != nil)
}

@ViewBuilder private var workroomTabsBar: some View {
  let tabs = store.displayedWorkroomTargets()
  // Show the bar during a create even before any tab resolves (issue #116) — it hosts the
  // provisional "Creating…" chip, so the bar can't be hidden just because `tabs` is still empty.
  if !tabs.isEmpty || store.creation != nil {
    WorkroomTabBar(
      tabs: tabs, selectedID: store.selectedTargetID,
      onSelect: { selectWorkroomTab($0) },
      chipPaneDrag: $workroomChipDrag,
      localize: { workroomChipLocal($0) },
      dropTarget: { workroomChipDropTarget(at: $0) }
    )
    .frame(maxWidth: .infinity)
  } else {
    Spacer(minLength: 0)
  }
}

/// The two-column `NavigationSplitView` core (sidebar + detail/inspector). The window chrome, modal
/// presentations, and lifecycle hooks layer on in `body` via the `root*` helpers below — each its own
/// function so the modifier chain type-checks within the compiler's budget. The fully-inline chain
/// timed out the type-checker on CI ("unable to type-check this expression in reasonable time"); this
/// is the same split-it-up reason `EdgeRevealSidebars`/`MenuStateValues`/`NewWorkroomPresenter` exist.
private var splitView: some View {
  // A hand-rolled split (sidebar | detail | inspector) instead of `NavigationSplitView`: the native
  // sidebar column drew an inset card with a ~30pt top toolbar-reserve that left an empty gap under
  // the custom title bar, and that inset isn't controllable. `SidebarColumn`/`InspectorColumn` are
  // our own resizable cards (same `sidebarCard` as the edge-reveal, so pinned == unpinned), giving
  // full control over their position. Visibility round-trips through `store.sidebarVisible` /
  // `showInspector` (the View-menu ticks + toggles); width persists per column to `Defaults`.
  // A *detail-only* NavigationSplitView: we keep it (vs a plain HStack) only for the window
  // toolbar/layering context it sets up — that's what lets the custom title bar, drawn in the
  // full-size content under the native title bar, render crisp instead of washed-out by the
  // title-bar vibrancy (a plain HStack / NavigationStack doesn't). Its native sidebar column is
  // never used (forced `.detailOnly`) — that column is what kept the ~30pt inset-card top gap — so
  // the real sidebar is our own `SidebarColumn` in the detail HStack, flush below the bar.
  // Wrapped in a *detail-only* `NavigationSplitView` (empty sidebar column, forced `.detailOnly`) —
  // NOT a plain HStack. A plain HStack detail in a full-size-content window with a visible `.unified`
  // toolbar loses SwiftUI `.onHover` for its content that sits near the top under the title bar (the
  // terminal tab strip's trailing toolbar buttons never lit their hover well — issue #114); the
  // title-bar region eats mouse-moved for a raw content view. `NavigationSplitView` hosts the detail
  // in an `NSSplitViewController`, which sets up the correct content tracking so `.onHover` fires
  // again. Dropping it (0e354d6e) was to stop it clipping `.toolbar { items }` to the sidebar-column
  // width — but the chrome no longer lives in toolbar items; it's a full-width window-level `.left`
  // `TitlebarAccessoryHost` (see `accessoryBarContent`), which NavigationSplitView does not clip. So
  // we get correct hover back with no clipping. The empty native sidebar column is unused — the real
  // sidebar is our own `SidebarColumn` in the detail HStack, flush below the bar.
  NavigationSplitView(columnVisibility: .constant(.detailOnly)) {
    Color.clear.frame(width: 0)
  } detail: {
    HStack(spacing: 0) {
      if store.sidebarVisible {
        SidebarColumn(
          paneDrag: $workroomChipDrag,
          localize: { workroomChipLocal($0) },
          dropTarget: { workroomChipDropTarget(at: $0) }
        )
        .transition(.move(edge: .leading))
      }
      detail
        .frame(maxWidth: .infinity, maxHeight: .infinity)
      if showInspector {
        InspectorColumn()
          .transition(.move(edge: .trailing))
      }
      // The activity bar is ALWAYS present, flush to the window's trailing edge — the inspector
      // content pane (above) slides in/out beside it. Placed inside the detail-only
      // NavigationSplitView so its icon buttons get working `.onHover` (issue #114).
      ActivityBar()
    }
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: store.sidebarVisible)
    .animation(reduceMotion ? nil : .easeInOut(duration: 0.2), value: showInspector)
  }
}

/// Error alert, add-project importer, and the new-workroom / workroom-delete / project-delete
/// presenters — all driven by store flags plus the `showImporter` state.
private func rootModals<V: View>(_ content: V) -> some View {
  content
    .alert(
      store.errorTitle ?? "Something went wrong",
      isPresented: Binding(
        get: { store.errorMessage != nil },
        set: {
          if !$0 {
            store.errorMessage = nil
            store.errorTitle = nil
          }
        }
      )
    ) {
      Button("OK", role: .cancel) {
        store.errorMessage = nil
        store.errorTitle = nil
      }
    } message: {
      Text(store.errorMessage ?? "")
    }
    // Add-project importer + delete confirmation, re-homed here from ProjectSidebar (issue #23 OV1) so
    // the ⌘O / ⌘⌫ menu commands present reliably even when the sidebar is collapsed in Workrooms View.
    // The triggers stay on the store (`requestAddProject` / `pendingDeletion`), set by both the menu
    // commands and the sidebar's own buttons.
    .onChange(of: store.requestAddProject) { _, request in
      if request {
        showAddProject = true
        store.requestAddProject = false
      }
    }
    .sheet(isPresented: $showAddProject) {
      AddProjectSheet(
        onAdd: { path, create in
          showAddProject = false
          Task { await store.addProject(path, create: create) }
        },
        onCancel: { showAddProject = false })
    }
    // New Workroom picker (⌘N, issue #81): same store-flag bridge as the importer above, packaged as
    // a modifier so this large `body` stays within the type-checker's budget (like EdgeRevealSidebars).
    // The menu command gates on `hasProjects`, so it only fires with ≥1 project; the dialog itself
    // still handles a filter that matches nothing.
    .modifier(NewWorkroomPresenter(store: store))
    // Open Workroom picker (⌘O, issue #94): same store-flag bridge, also gated on `hasProjects`.
    // One of several sibling `.sheet` presenters on this view — only one is ever active at a time.
    .modifier(OpenWorkroomPresenter(store: store))
    .confirmationDialog(
      store.pendingDeletion.map { "Delete '\($0.workroom.displayName)'?" } ?? "Delete workroom?",
      isPresented: Binding(
        get: { store.pendingDeletion != nil }, set: { if !$0 { store.pendingDeletion = nil } }),
      titleVisibility: .visible
    ) {
      Button("Delete", role: .destructive) {
        if let target = store.pendingDeletion {
          store.deleteWorkroom(target.workroom, in: target.project)
        }
        store.pendingDeletion = nil
      }
      Button("Cancel", role: .cancel) { store.pendingDeletion = nil }
    } message: {
      Text(
        "This removes the workroom's directory and runs its teardown script. For Git, the branch is left in place."
      )
    }
    // Tab bar "Close": tear down all of the workroom's terminal tabs (its chip leaves the bar),
    // leaving the workroom itself in place. Same store-flag → confirmationDialog bridge as delete.
    .confirmationDialog(
      store.pendingWorkroomClose.map { "Close ‘\($0.name)’?" } ?? "Close workroom?",
      isPresented: Binding(

    let plan = PaneTreeLayout.plan(layout, in: CGRect(origin: .zero, size: detailContentFrame.size))
    guard let hit = PaneTreeLayout.dropTarget(at: local, panes: plan.panes) else { return nil }
    return (sid: hit.tab, edge: hit.edge)
  }

  /// Focus a workroom tab — mirrors `ProjectSidebar`'s selection setter (sets both the target and the
  /// New-Workroom project context). The split is persistent (like a terminal split): selecting a member
  /// shows the split, selecting a non-member shows that workroom solo *without* dissolving the split —
  /// it reappears when a member is reselected (`visibleWorkroomLayout`). The split dissolves only by
  /// removing members below two.
  private func selectWorkroomTab(_ sid: SidebarID) {
    store.selectedTargetID = sid
    store.selectedProjectID = AppStore.projectPath(of: sid)
  }

  @ViewBuilder
  private var detailContent: some View {
    if store.isCreationFocused, let creation = store.creation {
      // The creating slot owns the detail (issue #116): a loader through the pre-name phase (and all
      // the way to the terminal for a no-setup workroom), swapped for the streaming setup dialog once
      // a setup script starts. Scoped to this focused slot — selecting another workroom shows it.
      creationDetail(creation)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    } else if let target = store.selectedTarget {
      if target.isMissing {
        ContentUnavailableView(
          "Directory not found",
          systemImage: "questionmark.folder",
          description: Text(
            "\(target.title) points at a path that no longer exists.\n\(target.path)")
        )
      } else {
        // The focused target's terminal body — ALWAYS rendered through `WorkroomSplitView` (a no-split
        // case is just `.leaf(selected)`), so single↔split is a leaf-set change, never a structural swap
        // that would re-parent the surface and blank a pane (issue #23, the same lesson as
        // `WorkroomTerminalsView` always rendering through `PaneTreeView`). Title/toolbar follow the
        // focused member (`selectedTarget`).
        // The run/stop/restart + "Open in…" controls now live in the title-bar toolbar
        // (`TrailingTitlebarBar`, driven by `store.selectedTarget`), not a detail `.toolbar`. The
        // window title/subtitle are dropped too — the workroom tabs already name the current workroom.
        workroomSplitBody(focused: target)
          .frame(maxWidth: .infinity, maxHeight: .infinity)
      }
    } else {
      ContentUnavailableView(
        "Nothing selected",
        systemImage: "terminal",
        description: Text(
          "Select a project's root or a workroom to open a terminal in its directory, or create one."
        )
      )
    }
  }

  /// The creating slot's detail (issue #116): a centered loader until a setup script's dialog is ready,
  /// then the streaming setup dialog. A workroom with no setup script never reaches the dialog — the
  /// loader shows until the create completes (which clears `store.creation`) and the terminal mounts.
  @ViewBuilder
  private func creationDetail(_ creation: WorkroomCreation) -> some View {
    if creation.targetID != nil, creation.hasSetup {
      SetupOverlay(session: creation.session) { store.dismissCreation() }
    } else {
      CreationLoader()
    }
  }

  /// The workroom body: always `WorkroomSplitView`, with the layout being the split when the selected
  /// workroom is a member, else `.leaf(selected)` — the split is shown only when a member is focused but
  /// persists otherwise (`visibleWorkroomLayout`, mirroring the terminal split). One render path → no
  /// reparent on single↔split. Falls back to the bare terminal body if somehow there's no selection id.
  @ViewBuilder
  private func workroomSplitBody(focused: TerminalTarget) -> some View {
    if let selected = store.selectedTargetID {
      WorkroomSplitView(
        store: store,
        layout: store.visibleWorkroomLayout(for: selected),
        resolve: { store.target(for: $0) },
        focusedID: selected,
        externalDrag: $workroomChipDrag,
        localize: { workroomChipLocal($0) },
        dropTarget: { workroomChipDropTarget(at: $0) },
        onFocus: { selectWorkroomTab($0) },
        onSetRatio: { store.setWorkroomSplitRatio($0, forSplit: $1) },
        onClose: { store.removeWorkroomSplitMember($0) },
        onMove: { store.insertWorkroomSplit($0, beside: $1, edge: $2) }
      )
    } else {
      targetTerminalBody(focused)
    }
  }

  /// One target's terminal body. While this workroom is being created with a setup script
  /// (`isCreationBlocking`), the terminal is withheld — `WorkroomTerminalsView` mounts (and `.task`
  /// creates the first terminal) only once the setup dialog is dismissed. The dialog itself is drawn
  /// window-level over the whole detail (see `detail`), not here, so this is just the terminal.
  @ViewBuilder
  private func targetTerminalBody(_ target: TerminalTarget) -> some View {
    if !store.isCreationBlocking(target.id) {
      WorkroomTerminalsView(target: target, sessions: store.terminals)
    }
  }
}

/// Publishes the per-window menu-command enablement values as `focusedSceneValue`s in one place. A
/// `Commands` body doesn't re-evaluate when the shared store mutates, but it does track focused
/// values — so RootView recomputes these (it observes the store/sessions) and the menu reads them via
/// `@FocusedValue` (see `WorkroomCommands`). Collapsed into a `ViewModifier` so RootView's body stays a
/// single, fast-to-type-check expression (a dozen inline `.focusedSceneValue` calls blow the
/// type-checker's budget).
private struct MenuStateValues: ViewModifier {
  let workroomSelected: Bool
  let hasNotifications: Bool
  let hasProjects: Bool
  let canNavigateBack: Bool
  let canNavigateForward: Bool
  let hasRunCommand: Bool
  let runCommandActive: Bool
  let hasRunTerminal: Bool
  let multipleWorkroomTabs: Bool
  let canOpenInEditor: Bool

