import SwiftUI

/// Hover/press chrome for the title-bar toolbar's icon buttons (sidebar toggle, back/forward, quick
/// terminal, run/stop/restart, bell, inspector toggle). Replaces the bare `.borderless` style so they
/// get the SAME affordance as every other icon button in the app — the sidebar's theme/add buttons and
/// the tab strips' "+" all use a `tokens.hover` rounded square on hover — instead of no feedback at all.
///
/// A `ButtonStyle` (not a per-button `.onHover` + manual background) so one modifier on each title-bar
/// bar covers all its buttons, including nested ones, and the hover rect sizes itself to each glyph.
struct ToolbarIconButtonStyle: ButtonStyle {
  func makeBody(configuration: Configuration) -> some View {
    Chrome(configuration: configuration)
  }

  /// A view (not an inline modifier chain) so it can hold the `@State hovering` a `ButtonStyle`'s
  /// `Configuration` doesn't carry, and read `isEnabled` to suppress hover on a disabled button.
  private struct Chrome: View {
    let configuration: Configuration
    @Environment(\.isEnabled) private var isEnabled
    @State private var hovering = false
    private let theme = ThemeService.shared

    var body: some View {
      configuration.label
        // A uniform tap target so every glyph gets the same square hover well, matching the sidebar's
        // 28pt buttons in spirit while staying compact enough for the 28pt-tall title-bar row.
        .frame(minWidth: 22, minHeight: 22)
        .padding(.horizontal, 3)
        .background(
          // Animate ONLY the hover fill's opacity — never the whole button. A view-tree
          // `.animation(.easeOut, value: hovering)` at the end of this chain would also animate the
          // *label's* layout: on hover-in the glyph's pixel-snapped origin can re-round by one device
          // pixel (release/optimized builds and fractional display scaling snap differently than a
          // Debug build on an integer-scale display), and the implicit animation interpolates that 1pt
          // re-round into a visible "slide then settle" of the icon (issue #78). Scoping the animation
          // to the fill keeps the glyph out of every animation transaction, so any re-round snaps
          // instantly and imperceptibly while the well still fades in.
          RoundedRectangle(cornerRadius: 6, style: .continuous)
            .fill(theme.tokens.hover)
            .opacity(hovering && isEnabled ? 1 : 0)
            .animation(.easeOut(duration: 0.12), value: hovering)
        )
        .contentShape(RoundedRectangle(cornerRadius: 6, style: .continuous))
        // Dim on press; dim further when disabled — restoring what `.borderless` gave. Without the
        // disabled case a disabled button (e.g. Back/Forward with no history) renders at full strength,
        // so it looks active yet never shows a hover well — reading as a broken/"missing" hover. The
        // dim makes "disabled, so no hover" legible; enabled buttons keep the hover fill.
        .opacity(configuration.isPressed ? 0.6 : (isEnabled ? 1 : 0.4))
        .onHover { hovering = $0 }
    }
  }
}

import SwiftUI

/// One icon-only toolbar action, styled to match the app's other small controls (the tab strip's
/// "+" new-terminal button, the remove-from-split ✕, the Changes-panel row hover toolbar): a small
/// glyph with a hover well, a tooltip, and an accessibility label + identifier (per the "tooltips on
/// all controls" convention). Carries its own `onHover` so the `.help` tooltip's tracking area is
/// reliably installed. Shared by the tab strip (issue #72) and the Changes panel (issue #93).
struct TabToolbarButton: View {
  let systemImage: String
  let help: String
  let accessibilityLabel: String
  let identifier: String
  let action: () -> Void
  @State private var hovering = false

  var body: some View {
    Button(action: action) {
      Image(systemName: systemImage)
        .font(.system(size: 11))
        .foregroundStyle(.secondary)
        .padding(4)
        .background(
          RoundedRectangle(cornerRadius: 5)
            .fill(ThemeService.shared.tokens.hover.opacity(hovering ? 1 : 0))
        )
        // The whole padded glyph — the hover well the user aims at — is hoverable/clickable, not just
        // the SF Symbol: transparent padding doesn't hit-test on its own, so without this the button's
        // real target was the ~13×10 image inside a ~24×20 well. Everything that keys off hover was
        // then dead in that ring: no well fill, no `.help` tooltip, no click — which is what "the tabs
        // toolbar buttons have no tooltips" actually was. Measured through the AX frame (13×10 → 24×20;
        // `TabStripOverflowUITests.testChromeGlyphButtonsClaimTheirWholeWell` locks it in).
        // A `.frame` will NOT do this — measured: the AX frame stays 13×10. Mirrors the strip's "+"
        // (`TerminalTabStrip.addTerminalButton`) and the inspector's header buttons, which have always
        // had their own content shape.
        .contentShape(Rectangle())
    }
    .buttonStyle(.plain)
    .onHover { hovering = $0 }
    .help(help)
    .accessibilityLabel(accessibilityLabel)
    .accessibilityIdentifier(identifier)
  }
}

}

/// The remove-from-split (✕) control for a workroom split member. Hosted in the split-group title bar
/// (`WorkroomSplitGroupTitleBar`, issue #110) — present above every member regardless of its terminal
/// count or a blocking setup script, which is why it no longer needs to ride the tab strip or a
/// setup-overlay corner. A view (not an inline button) so it carries its own `onHover` — which both
/// gives the subtle hover feedback the other strip controls have AND ensures the `.help` tooltip's
/// tracking area is installed (a bare `.help` without any hover tracking can silently fail to show).
struct CloseWorkroomPaneButton: View {
  let action: () -> Void
  @State private var hovering = false

  var body: some View {
    Button(action: action) {
      // `pip.exit` (a pane with an arrow leaving its corner) reads as "pop this workroom out of the
      // split", not "close the workroom" — the ✕ was ambiguous (issue #110).
      Image(systemName: "pip.exit")
        .font(.system(size: 10))
        .foregroundStyle(hovering ? .primary : .secondary)
    }
    .buttonStyle(.plain)
    .padding(.horizontal, 8)
    .contentShape(Rectangle())
    .onHover { hovering = $0 }
    .help("Remove this workroom from the split")
    .accessibilityLabel("Remove workroom from split")
    .accessibilityIdentifier("workroom.pane.close")
  }
}

