  struct Controls: Equatable {
    let openIn: Bool
    let run: Bool
    let removeFromSplit: Bool
  }

  static func controls(isMissing: Bool, projectPath: String?, multi: Bool) -> Controls {
    Controls(
      openIn: !isMissing, run: !isMissing && projectPath != nil, removeFromSplit: multi)
  }
}

