  /// with very different room: the window title bar packs six controls plus a stretchable tab strip into
  /// one row, while the workroom pane header (issue #139) has a whole pane width with nothing but a
  /// label on it — so its actions can read at a comfortable size instead of a cramped one.
  enum Size {
    case titlebar
    case paneHeader

    /// Minimum well side. 24pt still clears the header's 28pt row with 2pt to spare.
    var well: CGFloat { self == .titlebar ? 22 : 24 }

    /// Explicit glyph point size, or nil to inherit the ambient font. `.titlebar` inherits deliberately:
    /// that is what it has always done, and pinning a number here would risk shifting it by a fraction.
    var glyph: CGFloat? { self == .titlebar ? nil : 15 }

    /// One well's full horizontal footprint, padding included — for callers that reserve space for a
    /// control that isn't rendered yet (see `RunControls.reservedWidth`).
    var footprint: CGFloat { well + horizontalPadding * 2 }

    var horizontalPadding: CGFloat { 3 }
  }

  var size: Size = .titlebar

  func makeBody(configuration: Configuration) -> some View {
    Chrome(configuration: configuration, size: size)
  }

